import numpy as np, itertools
lines=open('initial.xyz').read().split('\n'); n=int(lines[0])
els=[];xyz=[]
for l in lines[2:2+n]:
    p=l.split(); els.append(p[0]); xyz.append([float(x) for x in p[1:4]])
X0=np.array(xyz); bonds=[tuple(b) for b in np.load('bonds.npy')]
# drop spurious bonds (HH, and CH != 1.09)
bonds=[(i,j) for i,j in bonds if not (els[i]=='H' and els[j]=='H')]
bonds=[(i,j) for i,j in bonds if not (sorted(els[i]+els[j])==['C','H'] and abs(np.linalg.norm(X0[i]-X0[j])-1.09)>0.05)]
print("bonds now", len(bonds))
d0={tuple(sorted((i,j))): np.linalg.norm(X0[i]-X0[j]) for i,j in bonds}
adj={i:set() for i in range(n)}
for i,j in bonds: adj[i].add(j); adj[j].add(i)
excl=set()
for i in range(n):
    for j in adj[i]:
        excl.add((min(i,j),max(i,j)))
        for k in adj[j]: excl.add((min(i,k),max(i,k)))
pairs=[(i,j) for i,j in itertools.combinations(range(n),2) if (i,j) not in excl]
def rmin(i,j):
    a,b=els[i],els[j]
    if a=='H' and b=='H': return 1.9
    if 'H' in (a,b): return 2.3
    return 2.7
heavy=[i for i in range(n) if els[i]!='H']
def energy(X):
    E=0.0
    for i,j in bonds:
        d=np.linalg.norm(X[i]-X[j]); E+=150.0*(d-d0[(i,j)])**2
    for i,j in pairs:
        d=np.linalg.norm(X[i]-X[j]); rm=rmin(i,j)
        if d<rm: E+=40.0*(rm-d)**2
    for i in heavy:
        E+=8.0*np.sum((X[i]-X0[i])**2)
    return E
def grad(X):
    g=np.zeros_like(X)
    for i,j in bonds:
        dv=X[i]-X[j]; d=np.linalg.norm(dv); f=300.0*(d-d0[(i,j)])
        g[i]+=f*dv/d; g[j]-=f*dv/d
    for i,j in pairs:
        dv=X[i]-X[j]; d=np.linalg.norm(dv); rm=rmin(i,j)
        if d<rm and d>1e-6:
            f=-80.0*(rm-d)
            g[i]+=f*dv/d; g[j]-=f*dv/d
    for i in heavy:
        g[i]+=16.0*(X[i]-X0[i])
    return g
X=X0.copy()
step=2e-4
E=energy(X)
for it in range(4000):
    g=grad(X); X=X-step*g; E=energy(X)
print("E final", round(E,2))
# verify
bad=[]
for i,j in pairs:
    d=np.linalg.norm(X[i]-X[j]); rm=rmin(i,j)
    if d<rm-0.05: bad.append((round(d,2),i,j,els[i],els[j]))
print("remaining clashes", len(bad), bad[:10])
# bond length sanity
dev=max(abs(np.linalg.norm(X[i]-X[j])-d0[(i,j)]) for i,j in bonds)
print("max bond dev", round(dev,3))
with open('initial_relaxed.xyz','w') as f:
    f.write(f"{n}\nrelaxed initial\n")
    for el,p in zip(els,X): f.write(f"{el} {p[0]:.6f} {p[1]:.6f} {p[2]:.6f}\n")
np.save('bonds_clean.npy', np.array(bonds))
